REPORT=OUT/'rapport_aircraft_a34.md'
HANDOFF=ROOT/'harness/handoffs/WTC1_AIRCRAFT_A34_HANDOFF.md'

def route():
    return ('AIRCRAFT-A35 : priorité à la compilation séparée MUMPS autorisée explicitement par Jeremy le 11 octobre 2026, selon la proposition A33, limitée à une heure. Installer les dépendances minimales dans Ubuntu WSL, conserver le solveur Windows, les sources épinglées, les licences et tous les journaux. Vérifier ensuite une sonde implicite fraîche et des témoins explicites de même version avant toute extension entière. La comparaison mécanique préparée reste différée : TYPE6/Isolid18/Ismstr0→2 déjà exécuté dans A29/A31 et TYPE6/Isolid24/Ismstr2, en gardant la géométrie, LAW12, ses axes, densité, masse, conditions aux faces, référence indépendante et seuils A34. '
      'Le TYPE6/Isolid24/Ismstr4 reste une référence en cache, sans ancien solveur relancé. Lire les paramètres réellement acceptés par Starter; arrêter une branche à la première erreur ou au premier échec affine, conserver les tentatives et leurs différences. '
      'Contrôler objectivité/inertie libre, flexion, champs, bilans, travail et raffinements avant prise courbe puis insertion entière. Une meilleure énergie seule ne qualifie pas le mécanisme. '
      'Accord humain reçu : « Oui, installer et compiler le solveur séparé ». Une compilation réussie ne qualifie pas encore la dynamique implicite. Aucun changement de masse/densité, RKE inventé ou cible de dommage connu. '
      'Propriétés de rupture, décollement et prises historiques non identifiées; LAW12 reste un témoin élastique. Meilleur impact entierA20=20ms; vidéo3D10secondes physiques incomplète. Publication suivanteA34+A35après scellage.')

def preserve():
    s=inspect.getsource(old_audit.preserve).replace('A32_preserved','A34_preserved').replace('updates_2026-10-11_aircraft_a30_a31','updates_2026-10-11_aircraft_a32_a33')
    exec(compile(s,__file__+'::preserve','exec'),globals());globals()['preserve']()

